import gurobipy as gp
from gurobipy import GRB
shelves = []
shelf_capacity = {}
products = []
product_value = {}
product_requirement = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'resource_id' in v and 'resource_capacity' in v:
        rid = str(v['resource_id'])
        shelves.append(rid)
        shelf_capacity[rid] = int(v['resource_capacity'])
    if 'item_name' in v and 'item_value' in v and ('resource_requirement' in v):
        pid = str(v['item_name'])
        products.append(pid)
        product_value[pid] = int(v['item_value'])
        product_requirement[pid] = int(v['resource_requirement'])
shelves = list(dict.fromkeys(shelves))
products = list(dict.fromkeys(products))
for rid in shelves:
    if rid not in shelf_capacity:
        raise ValueError(f'Missing capacity for shelf {rid}')
for pid in products:
    if pid not in product_value or pid not in product_requirement:
        raise ValueError(f'Missing value or requirement for product {pid}')
m = gp.Model('BigMart_Shelf_Allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((product_value[pid] * x[rid, pid] for rid in shelves for pid in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((product_requirement[pid] * x[rid, pid] for pid in products)) <= shelf_capacity[rid] for rid in shelves), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')